const input = $input.first().json;
const payload = input.body ?? input;
let loi = '';
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) loi = 'Payload phải là một đối tượng JSON.';
else if (!Array.isArray(payload.alerts) || payload.alerts.length === 0) loi = 'Trường alerts phải là mảng không rỗng.';
else {
  for (const [index, alert] of payload.alerts.entries()) {
    const status = alert?.status ?? payload.status;
    if (!alert || typeof alert !== 'object' || Array.isArray(alert)) { loi = `Cảnh báo thứ ${index + 1} không hợp lệ.`; break; }
    if (!['firing', 'resolved'].includes(status)) { loi = `Cảnh báo thứ ${index + 1} thiếu trạng thái hợp lệ.`; break; }
    if (!alert.labels?.alertname || !alert.fingerprint || !alert.startsAt || Number.isNaN(Date.parse(alert.startsAt))) { loi = `Cảnh báo thứ ${index + 1} thiếu alertname, fingerprint hoặc startsAt.`; break; }
    if (status === 'resolved' && (!alert.endsAt || Number.isNaN(Date.parse(alert.endsAt)))) { loi = `Cảnh báo phục hồi thứ ${index + 1} thiếu endsAt.`; break; }
  }
}
return [{ json: loi ? { trang_thai_kiem_tra: 'khong_hop_le', status: 'invalid', thong_bao: loi } : { trang_thai_kiem_tra: 'hop_le', payload } }];

const { payload_goc: payload, alert, status_nhom } = $json;
const labels = alert.labels ?? {};
const annotations = alert.annotations ?? {};
const status = alert.status ?? status_nhom;
const rawSeverity = String(labels.severity ?? annotations.severity ?? 'info').toLowerCase();
const severity = ['high', 'critical', 'cao'].includes(rawSeverity) ? 'cao' : ['medium', 'warning', 'trung_binh'].includes(rawSeverity) ? 'trung_binh' : 'thap';
return {
  fingerprint: String(alert.fingerprint),
  status,
  alert_name: String(labels.alertname),
  severity,
  provider: labels.provider ? String(labels.provider).toLowerCase() : null,
  service: labels.service ? String(labels.service).toLowerCase() : null,
  vlan: labels.vlan ? String(labels.vlan) : null,
  project_name: labels.project_name ?? labels.project ?? null,
  instance: labels.instance ?? null,
  job: labels.job ?? null,
  starts_at: new Date(alert.startsAt).toISOString(),
  ends_at: alert.endsAt && !alert.endsAt.startsWith('0001-') ? new Date(alert.endsAt).toISOString() : null,
  received_at: new Date().toISOString(),
  summary: annotations.summary ?? null,
  description: annotations.description ?? null,
  payload: { receiver: payload.receiver ?? null, status: payload.status ?? null, alert }
};

const parts = [$json.fingerprint, $json.status, $json.starts_at];
if ($json.status === 'resolved') parts.push($json.ends_at);
return { ...$json, event_key: parts.join('|') };

const results = $input.all().map((item) => item.json);
const states = results.map((item) => item.result_status);
let status = states.every((value) => value === 'duplicate') ? 'duplicate' : states.every((value) => value === 'resolved') ? 'resolved' : states.includes('created') ? 'created' : 'updated';
const messages = { created: 'Cảnh báo đã được lưu và tạo sự cố.', updated: 'Cảnh báo đã được lưu và cập nhật sự cố.', duplicate: 'Sự kiện trùng đã được bỏ qua.', resolved: 'Trạng thái phục hồi đã được xử lý.' };
return [{ json: { status, thong_bao: messages[status], so_canh_bao: results.length, ket_qua: results } }];
